package cn.bidcheck.verification.engine;
import cn.bidcheck.domain.Domain.Document;
import cn.bidcheck.domain.Domain.Page;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static cn.bidcheck.verification.engine.VerificationTypes.*;

class EnterpriseSubjectBindingsTest {
 private static final String PROJECT="北方中心综合楼装修工程",A="北方装饰有限公司",B="南方设计有限公司";
 private Rule rule(String predicate,String role){return new Rule("R", "提交有效营业执照",predicate,role,"营业执照","","营业执照","",Map.of(),"投标人须提交有效营业执照","",List.of());}
 private Page page(int number,String text){return new Page(number,text,"PAGE","TEXT",null);}
 private EvidenceCorpus corpus(String... text){List<Page> pages=new ArrayList<>();for(int i=0;i<text.length;i++)pages.add(page(i+1,text[i]));return new EvidenceCorpus(List.of(new Document("b","p","BID","商务文件",1,"h","",pages,List.of())));}
 private String cover(){return "1.商务投标文件封面\n（"+PROJECT+"）\n投标文件\n投标人名称：（盖章）"+A;}
 private String letter(){return "3.投标函\n（"+A+"和"+B+"联合体）（以下称“我方”）已仔细研究招标文件。\n投标人（公章或授权专用章）："+A;}
 private String agreement(String project){return "6.联合体协议书\n联合体协议书\n"+A+"、"+B+"[所有成员单位名称]自愿组成："+A+"和"+B+"联合体，共同投标"+project+"/标段。\n1. "+A+"为"+A+"和"+B+"联合体牵头人。\n"+A+"负责施工部分，"+B+"负责设计部分。";}
 private List<Fact> facts(EvidenceCorpus c,Rule r){return c.nativeFacts(List.of(r),List.of());}
 private Fact material(EvidenceCorpus c,int index,String company){return new Fact("material-"+company,"MATERIAL",company,"营业执照","营业执照","营业执照","","","CURRENT_PROJECT",List.of(c.all.get(index).id()),Map.of("contentPresent",true));}
 @Test void businessPredicatesShareExplicitBidderWithoutVisualRule(){for(String predicate:List.of("DECLARATION","MATERIAL","VALIDITY")){var c=corpus(cover());var r=rule(predicate,"投标人");assertEquals(List.of(A),DomainBindings.subjects("投标人",facts(c,r),c));}}
 @Test void fullCorpusBindingsDoNotDependOnRetrievedLicensePage(){var c=corpus(cover(),"营业执照\n名称："+A);assertEquals(List.of(A),DomainBindings.subjects("投标人",c.nativeFacts(List.of(rule("MATERIAL","投标人")),List.of(c.all.get(1))),c));}
 @Test void consortiumLetterEnumeratesBothNotOnlyCoverSigner(){var c=corpus(cover(),letter());assertEquals(Set.of(A,B),new HashSet<>(DomainBindings.subjects("投标人",facts(c,rule("MATERIAL","投标人")),c)));}
 @Test void exactCurrentAgreementResetsHistoricalAttachmentScopeAndKeepsRolesSeparate(){var c=corpus(cover(),"合同协议书\n项目名称：其他地区历史装修工程",agreement(PROJECT));assertEquals("CURRENT_PROJECT",c.all.get(2).scopeContext().status());for(var wanted:Map.of("投标人",Set.of(A,B),"联合体牵头人",Set.of(A),"设计单位",Set.of(B),"施工单位",Set.of(A)).entrySet())assertEquals(wanted.getValue(),new HashSet<>(DomainBindings.subjects(wanted.getKey(),facts(c,rule("MATERIAL",wanted.getKey())),c)),wanted.getKey());}
 @Test void allMembersRemainSeparateAndOneLicenseCannotPassBoth(){var c=corpus(cover(),letter(),"营业执照\n名称："+A+"\n经营范围：装饰施工，企业登记有效，依法开展经营活动。");var r=rule("MATERIAL","投标人");var fs=new ArrayList<>(facts(c,r));fs.add(material(c,2,A));Decision d=new RuleEvaluator(fs,c,Map.of()).evaluate(r);assertEquals("UNDETERMINED",d.status());assertEquals(Set.of(A,B),new HashSet<>((List<String>)d.proof().get("subjects")));assertEquals(2,((List<?>)d.proof().get("children")).size());assertFalse(((List<?>)d.proof().get("completeMemberSet")).isEmpty());}
 @Test void individualLicenseFactsCanPassOnlyTheirOwnSubmissionObligations(){var c=corpus(cover(),letter(),"营业执照\n名称："+A+"\n企业营业执照正文", "营业执照\n名称："+B+"\n企业营业执照正文");var r=rule("MATERIAL","投标人");var fs=new ArrayList<>(facts(c,r));fs.add(material(c,2,A));fs.add(material(c,3,B));var d=new RuleEvaluator(fs,c,Map.of()).evaluate(r);assertEquals("PASS",d.status(),d.toString());assertEquals(2,((List<?>)d.proof().get("children")).size());}
 @Test void licenseCannotSelfDeclareItsOwnerToBeBidder(){var c=corpus("投标文件\n项目名称："+PROJECT,"营业执照\n投标人名称："+A);assertTrue(facts(c,rule("MATERIAL","投标人")).isEmpty());}
 @Test void purchaserAndEmployerLabelsAreNeverBidderRoles(){var c=corpus("投标文件\n项目名称："+PROJECT+"\n招标人名称："+A+"\n甲方名称："+B);assertTrue(facts(c,rule("MATERIAL","投标人")).isEmpty());}
 @Test void placeholdersAndDirectoryAreNeverBindings(){for(String text:List.of("投标文件\n项目名称："+PROJECT+"\n投标人：XX装饰有限公司", "投标文件\n项目名称："+PROJECT+"\n填写示例\n投标人："+A,"目录\n投标文件...........1\n投标人...........2\n投标人："+A)){var c=corpus(text);assertTrue(facts(c,rule("MATERIAL","投标人")).isEmpty());}}
 @Test void foreignAgreementCannotResetCurrentProject(){var c=corpus(cover(),agreement("南方中心综合楼装修工程"));assertEquals("OTHER_PROJECT",c.all.get(1).scopeContext().status());assertEquals(List.of(A),DomainBindings.subjects("投标人",facts(c,rule("MATERIAL","投标人")),c));assertTrue(facts(c,rule("MATERIAL","联合体牵头人")).isEmpty());}
 @Test void nestedHistoricalHeadingOrExplicitForeignProjectWinsOverJointPhrase(){for(String text:List.of("历史项目\n"+agreement(PROJECT),agreement(PROJECT)+"\n项目名称：南方中心综合楼装修工程")){var c=corpus(cover(),text);assertTrue(c.all.get(1).scopeContext().blocked());assertTrue(facts(c,rule("MATERIAL","联合体牵头人")).isEmpty());}}
 @Test void conflictingCompleteMembershipDoesNotChooseConvenientSet(){var c=corpus(cover(),letter(),agreement(PROJECT).replace(B,"西部设计有限公司"));assertTrue(facts(c,rule("MATERIAL","投标人")).isEmpty());}
 @Test void incompleteActualJointAgreementCannotFallBackToCoverOnly(){var c=corpus(cover(),"联合体协议书\n共同投标"+PROJECT+"/标段。\n成员另见附件。");assertTrue(facts(c,rule("MATERIAL","投标人")).isEmpty());}
 @Test void cachedBindingAttributesNeverOverrideAbsentRoleSource(){var c=corpus("投标文件\n项目名称："+PROJECT,"营业执照\n名称："+A);var s=c.all.get(1);var forged=new Fact("fake","RELATION","投标人","名称",A,A,"","","CURRENT_PROJECT",List.of(s.id()),Map.of("object",A,"bindingMethod","EXPLICIT_BIDDER_LABEL","members",List.of(A)));assertFalse(EnterpriseSubjectBindings.grounded(forged,s));assertTrue(new ProofVerifier().verify(new ObjectMapper().valueToTree(Map.of("facts",List.of(forged))),c.all).facts().isEmpty());}
 @Test void validReusableBindingMustRevalidateCurrentSourceAndKeepsScopeNarrow(){var c=corpus(cover(),letter());var fs=facts(c,rule("MATERIAL","投标人"));assertFalse(fs.isEmpty());var checked=new ProofVerifier().verify(new ObjectMapper().valueToTree(Map.of("facts",fs)),c.all);assertEquals(fs.size(),checked.facts().size());assertTrue(checked.facts().stream().allMatch(f->"CURRENT_BID_PARTY_ONLY".equals(f.attributes().get("proofScope"))));}
 @Test void cachedSubsetCannotHideConflictingCompleteCurrentAgreement(){var c=corpus(cover(),letter(),agreement(PROJECT).replace(B,"西部设计有限公司"));var source=c.all.get(1);List<Fact> cached=new ArrayList<>();for(String company:List.of(A,B))cached.add(new Fact(company,"RELATION","投标人","名称",company,company,"","","CURRENT_PROJECT",List.of(source.id()),Map.of("object",company)));assertTrue(EnterpriseSubjectBindings.completeSet(List.of(A,B),c).isEmpty());assertEquals("SUBJECT_SET_INCOMPLETE",new RuleEvaluator(cached,c,Map.of()).evaluate(rule("MATERIAL","投标人")).gaps().get(0).code());}
 @Test void singleCachedCoverCompanyCannotHideExplicitJointBidWithMissingList(){var c=corpus(cover(),"投标函\n本次采用联合体方式投标，组成名单另见附件。");var s=c.all.get(0);var cached=new Fact("cached","RELATION","投标人","名称",A,A,"","","CURRENT_PROJECT",List.of(s.id()),Map.of("object",A));assertTrue(facts(c,rule("MATERIAL","投标人")).isEmpty());assertEquals("SUBJECT_SET_INCOMPLETE",new RuleEvaluator(List.of(cached),c,Map.of()).evaluate(rule("MATERIAL","投标人")).gaps().get(0).code());}
 @Test void conditionalConsortiumInstructionsDoNotMakeSingleBidJoint(){var c=corpus(cover(),"投标函\n如为联合体投标应提交协议。\n若本次采用联合体方式投标，应列明全部成员。");assertEquals(List.of(A),DomainBindings.subjects("投标人",facts(c,rule("MATERIAL","投标人")),c));}
 @Test void companyAndRoleLineWrapsRetainExplicitAgreementRelations(){var c=corpus(cover(),agreement(PROJECT).replace("联合体牵头人","联\n合体牵头人").replace("负责施工部分","负责施工\n部分"));assertEquals(List.of(A),DomainBindings.subjects("联合体牵头人",facts(c,rule("MATERIAL","联合体牵头人")),c));assertEquals(List.of(A),DomainBindings.subjects("施工单位",facts(c,rule("MATERIAL","施工单位")),c));}
 @Test void cachedFalseLeadCannotUseNearbyOtherPartyAsProof(){var c=corpus(cover(),agreement(PROJECT));var s=c.all.get(1);var forged=new Fact("fake-lead","RELATION","联合体牵头人","名称",B,B,"","","CURRENT_PROJECT",List.of(s.id()),Map.of("object",B,"bindingMethod","EXPLICIT_LEAD_MEMBER"));assertFalse(DomainBindings.currentRoleSource(forged,c.byId));assertTrue(new ProofVerifier().verify(new ObjectMapper().valueToTree(Map.of("facts",List.of(forged))),c.all).facts().isEmpty());}
 @Test void completeMemberSelectorsPreserveTwoConcreteCompanies(){var c=corpus(cover(),agreement(PROJECT));for(String role:List.of("联合体成员","联合体成员单位","各成员","全部成员","本项目联合体所有成员")){var r=rule("MATERIAL",role);var fs=facts(c,r);assertEquals(Set.of(A,B),new HashSet<>(DomainBindings.subjects(role,fs,c)),role);assertFalse(DomainBindings.completeMemberSet(role,DomainBindings.roleLinks(role,fs,c),DomainBindings.subjects(role,fs,c),c).isEmpty(),role);}}
 @Test void completeMemberSelectorsNeverBecomeLeadOnlyForPartialSource(){var c=corpus(cover(),"联合体协议书\n共同投标"+PROJECT+"/标段。\n"+A+"为联合体牵头人。\n其余成员另见附件。");for(String role:List.of("全部成员","各成员"))assertTrue(facts(c,rule("MATERIAL",role)).isEmpty());}
 @Test void publishedNativePartyEdgesReloadWithSourceValidationWithoutBusinessReadCredit(){var c=corpus(cover(),letter(),"营业执照扫描件");var r=rule("MATERIAL","投标人");var fs=facts(c,r);var fixture=new SharedFactReuseTest();var ledger=fixture.new MemoryLedger();List<Source> exact=fs.stream().flatMap(f->f.sourceIds().stream()).distinct().map(c.byId::get).toList();new SharedFactReuse(c,ledger.context(),"model","engine").publish(fs,exact,List.of(r),List.of(),false,"NATIVE");assertFalse(ledger.batches.isEmpty());assertTrue(ledger.batches.stream().allMatch(b->RuleEvaluator.maps(b.get("fieldCoverage")).isEmpty()&&!b.containsKey("extractionCoverage")));var reloaded=new SharedFactReuse(c,ledger.context(),"model","engine").lookup(List.of(r),c.all,List.of());assertEquals(Set.of(A,B),new HashSet<>(DomainBindings.subjects("投标人",reloaded,c)));assertEquals("UNDETERMINED",new RuleEvaluator(reloaded,c,Map.of()).evaluate(r).status());}
 @Test void initialComputationAlreadyKnowsCompaniesBeforeAnyBusinessExtraction(){var c=corpus(cover(),letter());ObjectMapper json=new ObjectMapper();var r=rule("MATERIAL","投标人");ModelGateway mock=new ModelGateway(){public boolean enabled(){return true;}public String identity(){return "enterprise-offline-test";}public com.fasterxml.jackson.databind.JsonNode request(String operation,Map<String,Object> input){return json.valueToTree(operation.equals("COMPILE")?Map.of("logic","ALL","rules",List.of(r)):Map.of("facts",List.of()));}};var cp=new cn.bidcheck.domain.Domain.Checkpoint("enterprise","营业执照","资格","HIGH","SEMANTIC_RESPONSE","","",r.sourceQuote(),"",true,true,true,null);Map<String,Object> result=new VerificationEngine(mock,null).evaluate(cp,c.documents,null,Map.of());Map<String,Object> initial=RuleEvaluator.maps(result.get("steps")).stream().filter(s->"RULE_COMPUTATION_INITIAL".equals(s.get("type"))).findFirst().orElseThrow();String output=initial.get("output").toString();assertTrue(output.contains(A)&&output.contains(B),output);assertFalse(output.contains("SUBJECT_RELATION_UNPROVEN"),output);}
}
